// ===== Isle of Emberfall - log (Woodcutting / Sawing) inventory-icon sheet (auto-generated) =====
// 32 tree logs, 8x4 grid of 64px cells, in TIER order (0..31: generic Logs ->
// Worldtree sapling). Repoint by the core log ladder: iterate ITEMS where d.log
// is set, EXCLUDE the NZ-native rakau_* variants and wood_offcuts/charcoal, sort
// by d.logTier, map cell N. (Ids aren't a clean sequence; tier4="pine_logs".)
// Content-aware sliced (icons overflow an even grid). See docs/consumable-icon-
// sprite-prompts.txt (SHEET: Logs).
"use strict";
(function(){
  if (typeof ASSET_DATA === "undefined") window.ASSET_DATA = {};
  ASSET_DATA["lg"] = "data:image/png;base64,";
  if (typeof SHEET_KEYS !== "undefined" && !SHEET_KEYS.includes("lg")) SHEET_KEYS.push("lg");
  if (typeof SHEET_TILE !== "undefined") SHEET_TILE["lg"] = 64;
  if (typeof SPR !== "undefined") for (let k = 0; k < 32; k++) SPR["i_lg" + k] = ["lg", k % 8, Math.floor(k / 8)];
  if (typeof ITEMS !== "undefined") {
    const logs = Object.keys(ITEMS)
      .filter(id => ITEMS[id].log && !/^rakau_/.test(id) && id !== "wood_offcuts" && id !== "charcoal")
      .map(id => ({ id, tier: ITEMS[id].logTier || 0 }))
      .sort((a, b) => a.tier - b.tier);
    logs.forEach((l, k) => { if (k < 32) ITEMS[l.id].icon = "i_lg" + k; });
  }
})();
